var t=`1175-chiles-en-nogada`;var n=`world-1175`;var a=`MX`;var o=`central-america-caribbean`;var r=8;var s=54;var l={en:`Chiles en Nogada`,ua:`Чилі ен ногада`};var g={en:`Chiles en Nogada is a dish from Mexico prepared with poblano pepper, ground pork, yellow onion, apple. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Чилі ен ногада, страва кухні країни Мексика, яку готують із таких продуктів: перець поблано, свинячий фарш, жовта цибуля, яблуко. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var d=[{en:`Cut the vegetables evenly and roast at 200°C for about 17 minutes until tender and lightly charred.`,ua:`Наріжте овочі рівномірно та запікайте при 200°C приблизно 17 хвилин до м’якості й легкої підпеченої скоринки.`,t:[`roasting`],m:17,i:[[`poblano-pepper`,8,`pcs`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`ground-pork`,460,`g`],[`yellow-onion`,170,`g`],[`apple`,180,`g`],[`pear`,170,`g`],[`raisin`,65,`g`]]},{en:`Hollow or prepare the vegetables, then fill with the prepared mixture without packing too tightly.`,ua:`Підготуйте овочі, за потреби вийміть серцевину, і наповніть начинкою, не утрамбовуючи надто щільно.`,t:[`stuffing-vegetables`],m:12,i:[]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`walnut`,200,`g`],[`whole-cow-milk`,280,`ml`],[`cream-cheese`,100,`g`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`pomegranate-arils`,120,`g`],[`parsley`,25,`g`]]}];var p={slug:t,id:n,country:`MX`,region:o,servings:8,minutes:54,title:l,text:g,steps:d};export{a as country,p as default,n as id,s as minutes,o as region,r as servings,t as slug,d as steps,g as text,l as title};